	/**
	 * Default Constructor
	 */
    public SoftwareLoadService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new SoftwareLoadEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(SoftwareLoadRepository.class) );
		this.validator		= applicationContext.getBean(SoftwareLoadValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		SoftwareLoad
	 */
		public SoftwareLoad createSoftwareLoad( CreateSoftwareLoadCommand command ) {

		SoftwareLoad entity = new SoftwareLoad();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSoftwareLoadId( command.getSoftwareLoadId() );
            entity.setVersion( command.getVersion() );
            entity.setLoadType( command.getLoadType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of SoftwareLoad {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateSoftwareLoadCommand
	 * @return		SoftwareLoad
	 */
	public SoftwareLoad updateSoftwareLoad( UpdateSoftwareLoadCommand command ) {

		SoftwareLoad entity = new SoftwareLoad();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setSoftwareLoadId( command.getSoftwareLoadId() );
            entity.setVersion( command.getVersion() );
            entity.setConnectedAircraft( command.getConnectedAircraft() );
            entity.setAvionicsSuite( command.getAvionicsSuite() );
            entity.setLoadType( command.getLoadType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of SoftwareLoad {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteSoftwareLoadCommand
	 */
	public void delete( DeleteSoftwareLoadCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getSoftwareLoadId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of SoftwareLoad {0} ", id );

	}

	/**
	 * Method to retrieve the SoftwareLoad via SoftwareLoadFetchOneSummary
	 * @param 	summary SoftwareLoadFetchOneSummary
	 * @return 	SoftwareLoadFetchOneResponse
	 */
	public SoftwareLoad getSoftwareLoad( SoftwareLoadFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "SoftwareLoadFetchOneSummary arg cannot be null" );

		SoftwareLoad entity = null;
		UUID id = summary.getSoftwareLoadId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a SoftwareLoad using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all SoftwareLoads
	 *
	 * @return 	List<SoftwareLoad>
	 */
    public List<SoftwareLoad> getAllSoftwareLoad() {
		List<SoftwareLoad> list = projector.findAll( new FindAllSoftwareLoadQuery() );
		return list;
	}

	/**
	 * assign ConnectedAircraft on SoftwareLoad
	 * @param		command AssignConnectedAircraftToSoftwareLoadCommand
	 */
	public void assignConnectedAircraft( AssignConnectedAircraftToSoftwareLoadCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignConnectedAircraft(command.getSoftwareLoadId(), command.getAssignment());

	}

